          "allied_telesis": "show interface brief\nshow vlan\nshow wan status\nshow ip interface vlan1 brief\nshow interface transceiver\nshow epsr\nshow spanning-tree\nshow mac address-table\nshow system log\nshow interface counters errors\ndebug switching\nshow running-config\nshow boot config",
          "datacom": "show vlan brief\nshow interface ethernet brief\nshow ip route\nshow erps brief\nshow vlan membership detail\nshow mac-address-table\nshow l2vpn\nshow ip bgp summary\nshow ip ospf neighbor\nshow erps detail\nshow oam 802.3ah\nshow ip bgp neighbor\nshow ip ospf database\nshow running-config vlan\nshow running-config router bgp\nshow running-config interface",
          "adtran": "show remote-devices-discovered\nshow remote-devices-discovered | include unconfigured\nshow remote-devices-discovered gpon-olt 1\nshow remote-devices\nshow remote-devices-discovered detail\nshow running-config | include remote-device"
